-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10693, 40, 'Überstundenzuschläge bei Vollzeit steuerfrei stellen (Bund)', 'Verbessert die Vergütung bezahlter Mehrarbeit, erreicht laut Auswertungen aber nur rund 1,4 % der Beschäftigten; unbezahlte Überstunden bleiben unberührt und mehr Mehrarbeit wird eher gefördert als ausgeglichen.', 'gemischt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2025/heft/12/beitrag/steuerfreie-ueberstundenzuschlaege-geringe-entlastung-problematische-verteilungswirkungen.html', 'bund', null, true, 'blind', null),
  (10694, 40, 'Wöchentliche statt tägliche Höchstarbeitszeit im Arbeitszeitgesetz (Bund)', 'Kann flexiblere Verteilung der Arbeitszeit erlauben; zugleich werden längere Arbeitstage möglich, die nach BAuA-Daten häufiger mit verkürzten Ruhezeiten und höherem Unfallrisiko einhergehen. EU-rechtlich zulässig.', 'gemischt', 'https://www.personalwirtschaft.de/?p=210267', 'bund', null, true, 'blind', null),
  (10695, 40, 'Arbeitszeiterfassung gesetzlich regeln und häufiger kontrollieren (Bund)', 'Ohne Erfassung verfallen laut BAuA-Befragungen rund 62 % der Überstunden, mit Erfassung auf Zeitkonto nur 11 %; die meisten Beschäftigten erfassen aber schon, und die Befunde sind Befragungszusammenhänge.', 'belegt', 'https://www.personalwirtschaft.de/?p=210267', 'bund', null, true, 'blind', null),
  (10696, 40, 'Recht auf befristete Arbeitszeitverkürzung mit Rückkehr ausweiten (Bund)', 'Erleichtert es, den Umfang dem Wunsch anzupassen; die bisherige Brückenteilzeit hatte laut IAB kaum messbare Wirkung, was mit starren Regeln erklärt wird, die eine Ausweitung lockern könnte.', 'gemischt', 'https://ideas.repec.org/p/iab/iabfob/202402.html', 'bund', null, true, 'blind', null),
  (10697, 40, 'Mobiles Arbeiten und Homeoffice rechtlich absichern und fördern (Bund)', 'Homeoffice senkt Konflikte zwischen Beruf und Familie vor allem bei hohem Anteil, fördert aber Arbeit am Abend und Wochenende; ohne Rechtsanspruch bleibt die Wirkung vom Arbeitgeber abhängig.', 'gemischt', 'https://www.zfk.de/uncategorized/studie-homeoffice-kann-konflikte-zwischen-beruf-und-familie-reduzieren', 'bund', null, true, 'blind', null),
  (10698, 40, 'Homeoffice und flexible Arbeitszeitmodelle im öffentlichen Dienst des Bundes (Bund)', 'Als Arbeitgeber direkt umsetzbar, erreicht aber nur Beschäftigte des Bundes, wo solche Modelle schon verbreitet sind; Wirkung auf Vereinbarkeit hängt vom Umfang ab.', 'offen', null, 'bund', null, true, 'blind', null),
  (10699, 40, 'Lohnersatz bei Familienpflegezeit und Arbeitszeitreduzierung für Pflege (Bund)', 'Setzt am Einkommensverlust bei Pflege-Freistellung an, den das bisherige Darlehen kaum auffängt; empfohlen vom unabhängigen Beirat, Wirkung in Deutschland aber nicht erprobt, Kosten mehrere Mrd. Euro jährlich.', 'offen', 'https://www.bmbfsfj.bund.de/bmbfsfj/aktuelles/alle-meldungen/empfehlungen-zur-familienpflegezeit-und-zum-familienpflegegeld-uebergeben-200050', 'bund', null, true, 'blind', null),
  (10700, 40, 'Bezahlte Freistellung des zweiten Elternteils nach der Geburt (Bund)', 'Studien aus Belgien zeigen mehr Beteiligung der Väter an der Betreuung, aber kaum Wirkung auf spätere Erwerbsmuster; die Freistellung umfasst nur wenige Wochen.', 'belegt', 'https://ideas.repec.org/p/upf/upfgen/1934.html', 'bund', null, true, 'blind', null),
  (10701, 40, 'Geldleistung für Eigenbetreuung kleiner Kinder zu Hause (Bund)', 'Ermöglicht Betreuung zu Hause ohne Einkommensverlust; das Thüringer Betreuungsgeld senkte aber die Erwerbstätigkeit vor allem gering verdienender Mütter. Bundeskompetenz ist strittig, Kosten hoch.', 'gemischt', 'https://idw-online.de/en/news470156', 'bund', null, true, 'blind', null)
