insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10702, 40, 11, null, 'Überstundenzuschläge bei Vollzeitbeschäftigung steuerfrei stellen.', '{4001}', 10693, 1, 3, null, 'Verbessert die Vergütung bezahlter Mehrarbeit, erreicht laut Auswertungen aber nur rund 1,4 % der Beschäftigten; unbezahlte Überstunden bleiben unberührt und mehr Mehrarbeit wird eher gefördert als ausgeglichen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2025/heft/12/beitrag/steuerfreie-ueberstundenzuschlaege-geringe-entlastung-problematische-verteilungswirkungen.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10703, 40, 11, null, 'Anstelle der täglichen Höchstarbeitszeit eine wöchentliche Höchstarbeitszeit im Arbeitszeitgesetz festlegen.', '{4001}', 10694, 1, 3, null, 'Kann flexiblere Verteilung der Arbeitszeit erlauben; zugleich werden längere Arbeitstage möglich, die nach BAuA-Daten häufiger mit verkürzten Ruhezeiten und höherem Unfallrisiko einhergehen. EU-rechtlich zulässig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.personalwirtschaft.de/?p=210267', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10704, 40, 11, null, 'Besondere Schutzerfordernisse bei gefahrgeneigten Berufen berücksichtigen.', '{4001}', null, 1, 3, null, 'Das Unfallrisiko steigt nach acht Stunden nachweislich; die Zusage, Schutzerfordernisse zu berücksichtigen, bleibt aber unbestimmt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', null, 'belegt', '2026-10-21', false, true, 'blind', null),
  (10705, 40, 11, null, 'Rechtssicherheit für mobiles Arbeiten und Homeoffice schaffen und mobile Arbeitsformen fördern.', '{4003}', 10697, 1, 3, null, 'Homeoffice senkt Konflikte zwischen Beruf und Familie vor allem bei hohem Anteil, fördert aber Arbeit am Abend und Wochenende; ohne Rechtsanspruch bleibt die Wirkung vom Arbeitgeber abhängig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=14', 'https://www.zfk.de/uncategorized/studie-homeoffice-kann-konflikte-zwischen-beruf-und-familie-reduzieren', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10706, 40, 11, null, 'Elterngeld verbessern und den Partnerschaftsbonus bei vollzeitnaher Teilzeit beider Eltern weiterentwickeln.', '{4003}', null, 1, 3, null, 'Elterngeld erleichtert Freistellung nach der Geburt; der Partnerschaftsbonus wurde laut DIW nur von rund 1 % der Familien genutzt, und die Verbesserung ist unbestimmt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=62', 'https://www.diw.de/de/diw_01.c.673403.de/publikationen/wochenberichte/2019_35/elterngeld_und_elterngeld_plus_nutzung_durch_vaeter_gestiegen_aufteilung_zwischen_muettern_und_....html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10707, 40, 12, null, 'Zuschläge für Mehrarbeit steuerfrei stellen', '{4001}', 10693, 1, 3, null, 'Verbessert die Vergütung bezahlter Mehrarbeit, erreicht laut Auswertungen aber nur rund 1,4 % der Beschäftigten; unbezahlte Überstunden bleiben unberührt und mehr Mehrarbeit wird eher gefördert als ausgeglichen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=24', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2025/heft/12/beitrag/steuerfreie-ueberstundenzuschlaege-geringe-entlastung-problematische-verteilungswirkungen.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10708, 40, 12, null, 'Steuerlich begünstigte Arbeitgeberprämie für mehr Stunden bei Teilzeitbeschäftigten', '{4002}', null, 1, 3, null, 'Steuerbegünstigte Prämien können Stundenaufstockungen in Teilzeit erleichtern; Mitnahmeeffekte sind wahrscheinlich und Hindernisse wie Betreuung bleiben unberührt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=24', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10709, 40, 12, null, 'Teilzeitmodelle und Job-Sharing im öffentlichen Dienst', '{4002}', null, 1, 3, null, 'Teilzeit und Job-Sharing im Bundesdienst erleichtern passende Arbeitsumfänge, erreichen aber nur Beschäftigte des Bundes, wo Teilzeit schon möglich ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10710, 40, 12, null, 'Kürzere Wochenarbeitszeit als Freizeitausgleich für Beschäftigte in Gesundheitsberufen', '{4002}', null, 1, 1, null, 'Kürzere Wochenarbeitszeit kann Belastung senken; der Bund kann sie für Gesundheitsberufe kaum festlegen (Tarifautonomie), Finanzierung und Personal sind offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=32', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10711, 40, 12, null, 'Ausbau vollzeitnaher Stellen in Kitas und Schulen im Rahmen einer Fachkräfteoffensive', '{4002}', null, 1, 2, null, 'Mehr vollzeitnahe Stellen helfen Beschäftigten, die länger arbeiten wollen; das Vorhaben zielt vor allem auf Fachkräfte und braucht eine Vereinbarung mit den zuständigen Ländern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10712, 40, 12, null, 'Freistellung von Vätern oder Partnern nach der Geburt mit Lohnfortzahlung', '{4003}', 10700, 1, 3, null, 'Studien aus Belgien zeigen mehr Beteiligung der Väter an der Betreuung, aber kaum Wirkung auf spätere Erwerbsmuster; die Freistellung umfasst nur wenige Wochen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://ideas.repec.org/p/upf/upfgen/1934.html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10713, 40, 12, null, 'Elterngeld mit nicht übertragbaren Monaten je Elternteil und weiteren frei verteilbaren Monaten', '{4003}', null, 2, 2, null, 'Partnermonate haben die Väterbeteiligung am Elterngeld deutlich erhöht, die meisten Väter nehmen aber nur das Minimum; mehr nicht übertragbare Monate dürften wirken, kosten aber erheblich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://www.diw.de/de/diw_01.c.673403.de/publikationen/wochenberichte/2019_35/elterngeld_und_elterngeld_plus_nutzung_durch_vaeter_gestiegen_aufteilung_zwischen_muettern_und_....html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10714, 40, 12, null, 'Familienpflegezeit und Familienpflegegeld für Vereinbarkeit von Pflege und Beruf', '{4003}', 10699, 2, 2, null, 'Setzt am Einkommensverlust bei Pflege-Freistellung an, den das bisherige Darlehen kaum auffängt; empfohlen vom unabhängigen Beirat, Wirkung in Deutschland aber nicht erprobt, Kosten mehrere Mrd. Euro jährlich.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=48', 'https://www.bmbfsfj.bund.de/bmbfsfj/aktuelles/alle-meldungen/empfehlungen-zur-familienpflegezeit-und-zum-familienpflegegeld-uebergeben-200050', 'offen', '2026-10-21', false, true, 'blind', null),
  (10715, 40, 12, null, 'Flächendeckendes Homeoffice im öffentlichen Dienst', '{4003}', 10698, 1, 3, null, 'Als Arbeitgeber direkt umsetzbar, erreicht aber nur Beschäftigte des Bundes, wo solche Modelle schon verbreitet sind; Wirkung auf Vereinbarkeit hängt vom Umfang ab.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10716, 40, 13, null, 'Arbeitszeiterfassung für alle Beschäftigte digital und unbürokratisch im Arbeitszeitgesetz regeln, in Schwarzarbeitsbranchen manipulationssicher', '{4001}', 10695, 2, 3, null, 'Ohne Erfassung verfallen laut BAuA-Befragungen rund 62 % der Überstunden, mit Erfassung auf Zeitkonto nur 11 %; die meisten Beschäftigten erfassen aber schon, und die Befunde sind Befragungszusammenhänge.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=68', 'https://www.personalwirtschaft.de/?p=210267', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10717, 40, 13, null, 'Brückenteilzeit und Rückkehrrecht in Vollzeit ausweiten und flexibler gestalten', '{4002}', 10696, 2, 3, null, 'Erleichtert es, den Umfang dem Wunsch anzupassen; die bisherige Brückenteilzeit hatte laut IAB kaum messbare Wirkung, was mit starren Regeln erklärt wird, die eine Ausweitung lockern könnte.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', 'https://ideas.repec.org/p/iab/iabfob/202402.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10718, 40, 13, null, 'Minijobs schrittweise in sozialversicherungspflichtige Beschäftigung überführen', '{4002}', null, 2, 2, null, 'Minijobs bilden laut IAB und ifo selten eine Brücke in längere Arbeitszeiten und setzen Fehlanreize; ob Betroffene nach der Umwandlung mehr arbeiten oder aussteigen, ist ungewiss.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=69', 'https://www.evangelisch.de/inhalte/178500/17-11-2020/studie-vor-allem-frauen-stecken-der-minijob-falle', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10719, 40, 13, null, 'Mehr Zeitsouveränität über Lage und Dauer der Arbeitszeit, für Vereinbarkeit mit Familie und Sorgearbeit', '{4003}', null, 1, 2, null, 'Mehr Einfluss auf Lage und Dauer der Arbeitszeit setzt an der Vereinbarkeit an; welches Instrument das leisten soll, bleibt offen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=68', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10720, 40, 13, null, 'Mobiles Arbeiten, auch im Homeoffice, mit klaren Regeln und fairen Absprachen', '{4003}', 10697, 1, 3, null, 'Homeoffice senkt Konflikte zwischen Beruf und Familie vor allem bei hohem Anteil, fördert aber Arbeit am Abend und Wochenende; ohne Rechtsanspruch bleibt die Wirkung vom Arbeitgeber abhängig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=68', 'https://www.zfk.de/uncategorized/studie-homeoffice-kann-konflikte-zwischen-beruf-und-familie-reduzieren', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10721, 40, 13, null, 'Familienstartzeit: zwei Wochen Freistellung mit Lohnersatz für Väter und Co-Mütter nach der Geburt', '{4003}', 10700, 1, 3, null, 'Studien aus Belgien zeigen mehr Beteiligung der Väter an der Betreuung, aber kaum Wirkung auf spätere Erwerbsmuster; die Freistellung umfasst nur wenige Wochen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=82', 'https://ideas.repec.org/p/upf/upfgen/1934.html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10722, 40, 13, null, 'Lohnersatz für die Zeit, in der Beschäftigte die Arbeitszeit zur Pflege reduzieren', '{4003}', 10699, 2, 2, null, 'Setzt am Einkommensverlust bei Pflege-Freistellung an, den das bisherige Darlehen kaum auffängt; empfohlen vom unabhängigen Beirat, Wirkung in Deutschland aber nicht erprobt, Kosten mehrere Mrd. Euro jährlich.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=92', 'https://www.bmbfsfj.bund.de/bmbfsfj/aktuelles/alle-meldungen/empfehlungen-zur-familienpflegezeit-und-zum-familienpflegegeld-uebergeben-200050', 'offen', '2026-10-21', false, true, 'blind', null),
  (10723, 40, 14, null, 'Arbeitszeitgesetz reformieren: wöchentliche statt tägliche Höchstarbeitszeit, flexible Arbeitszeitmodelle.', '{4001}', 10694, 1, 3, null, 'Kann flexiblere Verteilung der Arbeitszeit erlauben; zugleich werden längere Arbeitstage möglich, die nach BAuA-Daten häufiger mit verkürzten Ruhezeiten und höherem Unfallrisiko einhergehen. EU-rechtlich zulässig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=18', 'https://www.personalwirtschaft.de/?p=210267', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10724, 40, 14, null, 'Zuschläge für Überstunden bei Vollzeitarbeit von der Lohnsteuer befreien.', '{4001}', 10693, 1, 3, null, 'Verbessert die Vergütung bezahlter Mehrarbeit, erreicht laut Auswertungen aber nur rund 1,4 % der Beschäftigten; unbezahlte Überstunden bleiben unberührt und mehr Mehrarbeit wird eher gefördert als ausgeglichen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=14', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2025/heft/12/beitrag/steuerfreie-ueberstundenzuschlaege-geringe-entlastung-problematische-verteilungswirkungen.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10725, 40, 14, null, 'Arbeitszeitgesetz abschaffen, um flexible Arbeitszeiten zu ermöglichen; Vereinbarkeit von Beruf und Familie verbessern.', '{4003}', null, 1, 0, null, 'Flexible Arbeitszeiten können Vereinbarkeit erleichtern; die Abschaffung des Arbeitszeitgesetzes widerspricht aber der EU-Arbeitszeitrichtlinie mit Höchst- und Ruhezeiten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10726, 40, 15, null, 'Zulagen für Überstunden und Sondereinsätze bei Polizei und Rettungskräften, bundeseinheitliche Vergütung', '{4001}', null, 1, 1, null, 'Zulagen vergüten Mehrarbeit bei Polizei und Rettung besser, verringern sie aber nicht; bundeseinheitliche Besoldung erfordert eine Grundgesetzänderung.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=120', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10727, 40, 15, null, 'Förderprogramme sollen ermöglichen, in der Kleinkindphase ohne finanzielle Einbußen zu Hause zu bleiben oder Teilzeit zu arbeiten', '{4002}', 10701, 1, 1, null, 'Ermöglicht Betreuung zu Hause ohne Einkommensverlust; das Thüringer Betreuungsgeld senkte aber die Erwerbstätigkeit vor allem gering verdienender Mütter. Bundeskompetenz ist strittig, Kosten hoch.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=146', 'https://idw-online.de/en/news470156', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10728, 40, 15, null, 'Betreuungsgehalt bis zum dritten Geburtstag als Lohnersatz für Eigenbetreuung', '{4003}', 10701, 1, 1, null, 'Ermöglicht Betreuung zu Hause ohne Einkommensverlust; das Thüringer Betreuungsgeld senkte aber die Erwerbstätigkeit vor allem gering verdienender Mütter. Bundeskompetenz ist strittig, Kosten hoch.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=148', 'https://idw-online.de/en/news470156', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10729, 40, 16, null, 'Acht-Stunden-Tag als Obergrenze verteidigen; mindestens 11 Stunden Ruhezeit zwischen Schichten; Ausnahmen einschränken.', '{4001}', null, 1, 3, null, 'Lange Arbeitstage gehen mit höherem Unfall- und Gesundheitsrisiko einher; die Maßnahme bewahrt aber weitgehend geltendes Recht und schränkt Ausnahmen nur unbestimmt ein.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'belegt', '2026-10-21', false, true, 'blind', null),
  (10730, 40, 16, null, 'Wöchentliche Höchstarbeitszeit auf 40 Stunden begrenzen.', '{4001}', null, 2, 2, null, 'Arbeitszeiten über 40 Stunden pro Woche gelten als Gesundheitsrisiko, eine Obergrenze begrenzt Mehrarbeit direkt; sie schränkt aber Betriebe stark ein und ist schwer durchzusetzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'belegt', '2026-10-21', false, true, 'blind', null),
  (10731, 40, 16, null, 'Häufigere Kontrollen der Arbeitszeit mit unkomplizierten Nachweisen der Unternehmen per E-Mail.', '{4001}', 10695, 2, 3, null, 'Ohne Erfassung verfallen laut BAuA-Befragungen rund 62 % der Überstunden, mit Erfassung auf Zeitkonto nur 11 %; die meisten Beschäftigten erfassen aber schon, und die Befunde sind Befragungszusammenhänge.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://www.personalwirtschaft.de/?p=210267', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10732, 40, 16, null, 'Arbeitsunterbrechungen und Dienstzeiten müssen bezahlt werden.', '{4001}', null, 1, 2, null, 'Bezahlung von Arbeitsunterbrechungen und Dienstzeiten verringert unbezahlte Arbeitszeit; die Mehrarbeit selbst bleibt, Abgrenzung zu Pausen ist schwierig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10733, 40, 16, null, 'Arbeitszeitmodelle mit geringerer Wochenarbeitszeit (z. B. 32 Stunden oder Vier-Tage-Woche) bei vollem Lohn fördern.', '{4002}', null, 2, 1, null, 'Pilotprojekte zur Vier-Tage-Woche zeigen mehr Zufriedenheit und weniger Stress bei stabiler Produktivität, beruhen aber auf freiwilligen Teilnehmern; Lohn- und Personalausgleich sind nicht finanziert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://idw-online.de/-DNceAA', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10734, 40, 16, null, 'Recht auf vorübergehende Verkürzung der Arbeitszeit für alle Beschäftigten.', '{4002}', 10696, 2, 3, null, 'Erleichtert es, den Umfang dem Wunsch anzupassen; die bisherige Brückenteilzeit hatte laut IAB kaum messbare Wirkung, was mit starren Regeln erklärt wird, die eine Ausweitung lockern könnte.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', 'https://ideas.repec.org/p/iab/iabfob/202402.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10735, 40, 16, null, 'Sabbatjahr: Beschäftigte sollen zweimal im Berufsleben für ein Jahr aussteigen können, mit Rückkehrrecht.', '{4002}', null, 1, 2, null, 'Ein Sabbatjahr mit Rückkehrrecht schafft Auszeiten, ändert den Arbeitsumfang aber nur zeitweise; Finanzierung der Auszeit bleibt offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10736, 40, 16, null, 'Rechtsanspruch auf eine Vollzeitstelle, auch für familienfreundliche Schichten.', '{4002}', null, 2, 2, null, 'Ein Anspruch auf Vollzeit setzt direkt am unfreiwilligen Teilzeitumfang an; Wirkung hängt von Ausnahmen für Betriebe ab, Erfahrungen mit einem solchen Anspruch fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=27', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10737, 40, 16, null, 'Mobiles Arbeiten und flexible Betreuungsangebote ausbauen, damit Beruf und Familie besser zu vereinbaren sind.', '{4003}', 10697, 1, 3, null, 'Homeoffice senkt Konflikte zwischen Beruf und Familie vor allem bei hohem Anteil, fördert aber Arbeit am Abend und Wochenende; ohne Rechtsanspruch bleibt die Wirkung vom Arbeitgeber abhängig.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://www.zfk.de/uncategorized/studie-homeoffice-kann-konflikte-zwischen-beruf-und-familie-reduzieren', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10738, 40, 16, null, 'Für den zweiten Elternteil 28 Tage Elternschutz nach der Geburt einführen.', '{4003}', 10700, 1, 3, null, 'Studien aus Belgien zeigen mehr Beteiligung der Väter an der Betreuung, aber kaum Wirkung auf spätere Erwerbsmuster; die Freistellung umfasst nur wenige Wochen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=16', 'https://ideas.repec.org/p/upf/upfgen/1934.html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10739, 40, 16, null, 'Sechs Wochen Freistellung mit vollem, arbeitgeberfinanziertem Lohnausgleich bei einem familiären Pflegefall.', '{4003}', null, 2, 2, null, 'Bezahlte Freistellung beim Eintritt eines Pflegefalls verschafft Zeit zur Organisation ohne Einkommensverlust; die volle Finanzierung durch Arbeitgeber belastet kleine Betriebe, Erfahrungen fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10740, 40, 17, null, 'Flexible Arbeitszeitmodelle in den Verwaltungen einführen', '{4003}', 10698, 1, 3, null, 'Als Arbeitgeber direkt umsetzbar, erreicht aber nur Beschäftigte des Bundes, wo solche Modelle schon verbreitet sind; Wirkung auf Vereinbarkeit hängt vom Umfang ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', null, 'offen', '2026-10-21', false, true, 'blind', null);

